const labels={dashboard:'数据看板',competitions:'赛事管理',stages:'赛段管理',units:'参赛单位管理',users:'参赛用户管理',checkin:'签到规则配置',learning:'学习规则配置',gate:'闯关规则配置',points:'积分管理',ranking:'排行榜管理',promotion:'晋级管理',details:'积分明细'};
const names=['王晓磊','李雯','赵勇','陈志远','刘子豪','周静','杨帆','何军'];
function h5Go(id){document.querySelectorAll('.h5-view').forEach(x=>x.classList.remove('active'));const target=document.getElementById(id);if(target)target.classList.add('active');const tabbar=document.querySelector('.h5-tabbar');if(tabbar)tabbar.style.display=id==='login'?'none':'flex';document.querySelectorAll('.h5-tabbar button').forEach(x=>x.classList.toggle('active',x.dataset.tab===id));if(document.querySelector('.h5-page')){document.querySelectorAll('#points .point-record').forEach(x=>{if(x.textContent.includes('积分兑换'))x.remove()});document.querySelectorAll('#points .empty-p1').forEach(x=>x.remove());document.querySelectorAll('.h5-page *').forEach(x=>{if(x.children.length===0){x.textContent=x.textContent.replaceAll('基础能力提升赛','初赛阶段').replaceAll('基础赛段','初赛阶段').replaceAll('基础赛','初赛阶段').replaceAll('专项技能挑战赛','复赛阶段').replaceAll('专项赛','复赛阶段')}})}window.scrollTo(0,0)}
function openSign(){document.getElementById('signModal')?.classList.add('show')}function closeSign(){document.getElementById('signModal')?.classList.remove('show')}function selectOption(el){document.querySelectorAll('.question-option').forEach(x=>x.classList.remove('selected'));el.classList.add('selected')}
function showToast(message){const t=document.getElementById('toast');if(!t)return;t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}
const button=(text,primary=true,action='showToast(\'演示操作已完成，正式版本将提交至平台后台\')')=>`<button class="${primary?'btn-primary':'btn-secondary'}" onclick="${action}">${text}</button>`;
const metrics=(enterprise=false)=>{const data=enterprise?[['参赛人数','1,248','较昨日 +36',''],['参与率','91.6%','目标 90%',''],['累计积分','486,230','本周 +12.8%',''],['晋级候选','158','待企业确认','warn']]:[['报名人数','8,426','较昨日 +126',''],['赛事参与率','87.4%','较昨日 +2.1%',''],['累计发放积分','3,862,560','本周 +18.6%',''],['晋级候选人数','986','今日新增 48 人','warn']];return `<div class="metric-grid">${data.map(x=>`<div class="metric-card"><small>${x[0]}</small><b>${x[1]}</b><span class="${x[3]}">↗ ${x[2]}</span></div>`).join('')}</div>`};
function chart(){return `<div class="chart-wrap">${[42,68,52,88,73,91,80,96,76,84,98,89].map((v,i)=>`<div class="bar" style="height:${v}%" data-week="${i+1}日"></div>`).join('')}</div>`}
function dashboard(enterprise=false){const title=enterprise?'本单位数据看板':'竞赛数据看板';return `<div class="page-heading"><div><h1>${title}</h1><p>2026 年岗位技能竞赛 · 基础能力提升赛 · 数据截至 2026-06-23 09:30</p></div><div class="toolbar">${button('导出数据',false,"showToast('已生成 Excel 导出任务')")}${button('刷新数据')}</div></div>${metrics(enterprise)}<div class="dashboard-grid"><section class="panel"><div class="panel-title"><span>${enterprise?'单位':'全赛事'}参与趋势</span><a>近 14 天⌄</a></div>${chart()}</section><section class="panel"><div class="panel-title"><span>赛段推进</span><a>查看详情</a></div><div class="flow-line"><div class="flow-step done"><span>报名启动</span><small>已完成</small></div><div class="flow-step active"><span>基础提升</span><small>进行中</small></div><div class="flow-step"><span>专项挑战</span><small>待启动</small></div><div class="flow-step"><span>总决赛</span><small>待启动</small></div></div><div class="p1-box">AI 竞赛运营助手（P1）<br/>自动分析低参与人群并生成提醒建议</div></section></div><div class="dashboard-grid"><section class="panel"><div class="panel-title"><span>${enterprise?'单位':'全局'}积分排名 TOP 5</span><a>查看排行榜</a></div>${names.slice(0,5).map((n,i)=>`<div class="rank-row"><div class="rank-num">${i<3?['🥇','🥈','🥉'][i]:i+1}</div><div class="rank-avatar">${n[0]}</div><div><b>${n}</b><small>${enterprise?'电解一车间':'千铝工投 · 电解一车间'}</small></div><strong>${2680-i*120}</strong></div>`).join('')}</section><section class="panel"><div class="panel-title"><span>运营提醒</span><a>全部</a></div><div class="notice-item"><b>158 名用户已满足晋级条件</b><small>可进入「晋级管理」确认名单</small></div><div class="notice-item"><b>3 家单位参与率低于 70%</b><small>建议发送参赛提醒</small></div><div class="notice-item"><b>安全生产闯关通过率 62%</b><small>较上周提升 8%</small></div><div class="notice-item"><b>今日已完成签到 ${enterprise?'1,068':'6,218'} 人</b><small>签到率 ${enterprise?'85.6':'73.8'}%</small></div></section></div>`}
function tablePage(type,enterprise=false){const conf={competitions:['赛事管理','管理赛事基本信息、状态与赛段进度',['赛事名称','赛事时间','参赛单位','参赛人数','状态']],stages:['赛段管理','将赛事拆分为可独立配置、统计和晋级的阶段',['赛段名称','所属赛事','时间范围','积分上限','状态']],units:['参赛单位管理','查看与维护参赛企业、组织及其参赛状态',['单位名称','所属区域','参赛人数','参与率','状态']],users:[enterprise?'本单位用户管理':'参赛用户管理','管理参赛资格，支持批量导入、导出和状态维护',['姓名','所属单位','部门/车间','当前积分','参赛状态']],checkin:[enterprise?'签到记录':'签到规则配置',enterprise?'查看本单位用户每日签到情况':'配置签到积分、补签与连续签到激励',['用户/规则','关联赛段','今日状态','积分/奖励','操作']],learning:[enterprise?'学习记录':'学习规则配置',enterprise?'追踪课程学习完成与学后答题情况':'配置课程学习、学后答题与积分奖励',['用户/规则','课程/任务','完成进度','获得积分','状态']],gate:[enterprise?'闯关记录':'闯关规则配置',enterprise?'追踪用户分类闯关、关卡通过情况':'配置闯关分类、题目来源与通关奖励',['用户/规则','关卡分类','通关情况','获得积分','状态']],points:[enterprise?'用户积分':'积分管理',enterprise?'查看与调整本单位用户竞赛积分':'统一管理积分规则、发放、扣减和调整记录',['用户/积分项','所属赛段','当前积分','最近变动','状态']],details:['积分明细','按用户、赛段和积分来源追溯每一笔积分流水',['用户','积分来源','变动值','发生时间','备注']]};const x=conf[type];const isRule=['checkin','learning','gate'].includes(type)&&!enterprise;if(isRule)return configPage(type,x[0],x[1]);return `<div class="page-heading"><div><h1>${x[0]}</h1><p>${x[1]}</p></div><div class="toolbar">${button('导出',false,"showToast('已生成导出文件')")}${button(type==='competitions'?'新建赛事':type==='stages'?'新建赛段':type==='users'?'导入用户':'批量操作')}</div></div><div class="data-table-wrap"><div class="table-filter"><input placeholder="搜索名称 / 工号"/><select><option>全部赛段</option><option>基础能力提升赛</option></select><select><option>全部状态</option><option>进行中</option><option>已完成</option></select>${button('查询')}</div><table class="data-table"><thead><tr>${x[2].map(h=>`<th>${h}</th>`).join('')}<th>操作</th></tr></thead><tbody>${Array.from({length:6},(_,i)=>row(type,i,enterprise)).join('')}</tbody></table></div><div class="p1-box">智能筛选与异常数据诊断（P1） · 当前仅作需求占位</div>`}
function row(type,i,enterprise){const n=names[i];let data;if(type==='competitions')data=['2026 年岗位技能竞赛','2026-06-01 至 08-31','32 家','8,426 人','<span class="status green">进行中</span>'];else if(type==='stages')data=[['报名与预热','基础能力提升赛','专项技能挑战赛','总决赛'][i%4],'2026 年岗位技能竞赛','2026-06-01 至 06-30','2,000 分','<span class="status blue">进行中</span>'];else if(type==='units')data=[['千铝工投','绿色铝业','华东铝业','新材料公司'][i%4],'云南 · 昆明',`${1248-i*78} 人`,`${91-i*3}.6%`,'<span class="status green">已参赛</span>'];else if(type==='checkin')data=[n,'基础能力提升赛',i%3?'已签到':'未签到',i%3?'+5 积分':'—',i%3?'<span class="status green">正常</span>':'<span class="status orange">待跟进</span>'];else if(type==='learning')data=[n,'铝电解安全生产规范',`${65+i*5}%`,`+${20+i*2} 积分`,i>3?'<span class="status gray">未开始</span>':'<span class="status blue">学习中</span>'];else if(type==='gate')data=[n,'安全生产',`${i+1} / 5 关`,`+${30+i*10} 积分`,i>3?'<span class="status orange">挑战中</span>':'<span class="status green">已通关</span>'];else if(type==='points')data=[n,enterprise?'基础赛段':'累计竞赛积分',`${1310-i*86}`,'今天 +30','<span class="status green">正常</span>'];else if(type==='details')data=[n,['每日签到','课程学习','闯关成功'][i%3],`+${[5,20,30][i%3]}`,'2026-06-23 09:36','自动发放'];else data=[n,enterprise?'电解一车间':'千铝工投',i%2?'铸造车间':'电解一车间',`${1310-i*87}`,'<span class="status green">参赛中</span>'];return `<tr>${data.map(v=>`<td>${v}</td>`).join('')}<td><a class="text-link" onclick="showToast('已打开详情抽屉（原型演示）')">查看</a><a class="text-link">编辑</a></td></tr>`}
function configPage(type,title,desc){const rules={checkin:[['每日签到','每次签到奖励 5 积分'],['连续签到奖励','连续 7 天额外奖励 20 积分'],['补签规则','每赛段可补签 2 次']],learning:[['学习完成奖励','完成课程学习奖励 20 积分'],['学后答题奖励','答题正确率≥80% 奖励 10 积分'],['学习有效时长','视频学习时长达到 80% 才计完成']],gate:[['关卡通关奖励','每关通关奖励 30 积分'],['重复挑战规则','重复挑战仅保留最高分'],['分类解锁条件','累计积分达到门槛后解锁']]}[type];return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="toolbar">${button('保存配置')}</div></div><div class="config-grid"><section class="form-panel"><h3 style="margin-top:0">当前赛段基础设置</h3><div class="form-row"><label>适用赛事</label><select><option>2026 年岗位技能竞赛</option></select></div><div class="form-row"><label>适用赛段</label><select><option>基础能力提升赛</option></select></div><div class="form-row"><label>规则生效时间</label><input value="2026-06-01 00:00 至 2026-06-30 23:59"/></div><div class="form-row"><label>操作说明</label><input value="规则变更后实时影响后续参与记录"/></div><div style="text-align:right;margin-top:30px">${button('预览用户端',false,"showToast('已打开用户端规则预览')")} ${button('保存并发布')}</div></section><section class="form-panel"><div class="panel-title"><span>规则项</span><a>+ 新增规则</a></div>${rules.map((r,i)=>`<div class="rule-card"><div class="rule-left"><div class="rule-icon">${['☀','✦','✓'][i]}</div><div><b>${r[0]}</b><p>${r[1]}</p></div></div><div class="toggle"></div></div>`).join('')}<div class="p1-box">复杂积分公式与规则版本回溯（P1）</div></section></div>`}
function ranking(){return `<div class="page-heading"><div><h1>排行榜管理</h1><p>维护个人榜、单位榜展示规则，支持赛段快照与榜单导出</p></div><div class="toolbar">${button('导出排行榜',false,"showToast('排行榜导出任务已创建')")}${button('发布榜单')}</div></div><div class="panel" style="margin-bottom:14px"><div class="panel-title"><span>榜单展示配置</span><a>查看用户端效果</a></div><div class="form-row"><label>当前榜单</label><select><option>基础能力提升赛 · 个人积分榜</option></select></div><div class="form-row"><label>刷新频率</label><select><option>实时更新（5 分钟）</option></select></div><div class="form-row"><label>展示范围</label><select><option>展示前 100 名及本人排名</option></select></div></div><div class="data-table-wrap rank-table"><table class="data-table"><thead><tr><th>排名</th><th>参赛用户</th><th>所属单位</th><th>学习积分</th><th>闯关积分</th><th>总积分</th><th>趋势</th></tr></thead><tbody>${names.slice(0,6).map((n,i)=>`<tr><td class="medal">${i<3?['🥇','🥈','🥉'][i]:i+1}</td><td>${n}</td><td>${['千铝工投','绿色铝业'][i%2]}</td><td>${820-i*30}</td><td>${1860-i*90}</td><td><b>${2680-i*120}</b></td><td style="color:#19a76e">↑ ${i+1}</td></tr>`).join('')}</tbody></table></div>`}
function promotion(enterprise=false){return `<div class="page-heading"><div><h1>${enterprise?'条件晋级':'晋级管理'}</h1><p>${enterprise?'识别本单位满足条件的用户，提交晋级确认':'按赛段规则自动计算候选名单，进行确认、驳回与批量晋级'}</p></div><div class="toolbar">${button('导出候选名单',false,"showToast('候选名单已导出')")}${button(enterprise?'提交晋级确认':'批量确认晋级')}</div></div><div class="promotion-board"><section class="promotion-card"><span class="status blue">当前赛段 · 基础能力提升赛</span><h3 style="margin-top:13px">晋级条件</h3><div class="promotion-score">≥ 1,500</div><p style="color:#8290a5">累计积分达到门槛，且完成 2 门必修课程、3 个闯关分类</p><div class="p1-box">自动补位、同分排序及申诉流程（P1）</div></section><section class="promotion-card"><span class="status green">自动计算结果</span><h3 style="margin-top:13px">本轮候选</h3><div class="promotion-score">${enterprise?'158':'986'} 人</div><p style="color:#8290a5">${enterprise?'已满足积分及任务条件 · 待单位管理员确认':'已满足赛事晋级规则 · 待超级管理员发布'}</p><button class="btn-primary" style="margin-top:16px" onclick="showToast('已完成候选条件复核')">重新计算候选</button></section></div><div class="data-table-wrap" style="margin-top:14px"><div class="table-filter"><input placeholder="搜索姓名、工号"/><select><option>全部结果</option><option>符合条件</option><option>待补齐任务</option></select>${button('筛选')}</div><table class="data-table"><thead><tr><th>用户</th><th>所属单位</th><th>当前积分</th><th>必修课</th><th>闯关分类</th><th>条件判定</th><th>晋级状态</th><th>操作</th></tr></thead><tbody>${names.slice(0,6).map((n,i)=>`<tr><td>${n}</td><td>${enterprise?'千铝工投':'千铝工投'}</td><td>${1830-i*55}</td><td>2 / 2</td><td>${3+i%2} / 3</td><td><span class="status green">符合条件</span></td><td>${i===0?'<span class="status blue">已确认</span>':'<span class="status orange">待确认</span>'}</td><td><a class="text-link" onclick="showToast('已更新晋级状态')">确认晋级</a></td></tr>`).join('')}</tbody></table></div>`}
function renderSuper(page){const content=document.getElementById('superContent');if(!content)return;const map={dashboard:()=>dashboard(),competitions:()=>tablePage('competitions'),stages:()=>stagesPage(),units:()=>tablePage('units'),users:()=>tablePage('users'),checkin:()=>tablePage('checkin'),learning:()=>tablePage('learning'),gate:()=>tablePage('gate'),points:()=>tablePage('points'),ranking, promotion:()=>promotion(false)};content.innerHTML=(map[page]||map.dashboard)();document.getElementById('crumb').textContent=labels[page]||labels.dashboard;bindControls()}
function stagesPage(){const stages=[['报名与预热','2026-06-01 至 06-07','已结束','报名 8,426 人'],['基础能力提升赛','2026-06-08 至 06-30','进行中','参与率 87.4%'],['专项技能挑战赛','2026-07-01 至 07-31','待开始','已配置 5 类闯关']];const flow=stages.map((x,i)=>`<article class="stage-flow-card ${i===1?'active':''}"><div class="stage-number"><span>赛段 0${i+1}</span><span class="status ${i===1?'green':'gray'}">${x[2]}</span></div><h3>${x[0]}</h3><p>时间：${x[1]}<br/>任务：学习、答题、闯关<br/>${x[3]}</p><div class="stage-foot"><a class="text-link" onclick="showToast('打开赛段配置')">配置规则</a><a class="text-link">查看数据</a></div></article>${i<stages.length-1?'<div class="stage-flow-arrow" aria-label="流程进入下一赛段"><span>➜</span></div>':''}`).join('');return `<style>.stage-flow{display:flex;align-items:stretch;gap:0;overflow-x:auto;padding:4px 2px 15px;margin:0 -2px}.stage-flow-card{min-width:250px;flex:1;padding:17px;border:1px solid var(--line);border-radius:12px;background:#fff;box-shadow:0 4px 13px rgba(29,62,111,.035)}.stage-flow-card.active{border-color:#a8d0ff;background:linear-gradient(145deg,#fff,#f3f9ff);box-shadow:0 9px 21px rgba(22,119,255,.12)}.stage-flow-card .stage-number{display:flex;justify-content:space-between;color:#7b899e}.stage-flow-card h3{font-size:16px;margin:13px 0 8px}.stage-flow-card p{font-size:12px;line-height:1.7;color:#8793a4}.stage-flow-card .stage-foot{padding-top:12px;border-top:1px solid #edf1f5;font-size:12px}.stage-flow-arrow{width:62px;min-width:62px;position:relative;display:flex;align-items:center;justify-content:center}.stage-flow-arrow:before{content:"";position:absolute;top:50%;left:8px;right:7px;height:3px;border-radius:4px;background:#8bc1ff}.stage-flow-arrow span{position:relative;z-index:1;width:25px;height:25px;display:grid;place-items:center;border-radius:50%;color:#fff;font-size:15px;background:var(--blue);box-shadow:0 0 0 5px #f5f7fb}.stage-add{min-width:190px;flex:none;display:grid;place-items:center;align-content:center;gap:8px;border:1px dashed #a9bed9;border-radius:12px;color:#6281a7;background:#fbfdff}.stage-add b{display:grid;place-items:center;width:31px;height:31px;border-radius:50%;background:#e8f3ff;color:var(--blue);font-size:23px}.stage-add small{font-size:12px}</style><div class="page-heading"><div><h1>赛段管理</h1><p>以可扩展的赛事流程编排赛段，支持根据不同赛事按需新增、调整或串联赛段</p></div><div class="toolbar">${button('新建赛段',true,"showToast('已打开新增赛段配置（原型演示）')")}</div></div><section class="panel"><div class="panel-title"><span>2026 年岗位技能竞赛 · 赛事流程</span><a onclick="showToast('可拖拽调整赛段顺序（P1）')">调整流程顺序</a></div><div class="stage-flow">${flow}<button class="stage-add" onclick="showToast('可在此插入新的赛事赛段')"><b>+</b><strong>新增赛段</strong><small>可插入任意流程节点</small></button></div></section><div class="p1-box">赛事流程模板、赛段拖拽排序和分支赛道配置（P1） · 当前原型展示为可连续扩展的线性赛程</div><div class="data-table-wrap" style="margin-top:14px"><table class="data-table"><thead><tr><th>赛段名称</th><th>起止时间</th><th>积分池</th><th>晋级条件</th><th>状态</th><th>操作</th></tr></thead><tbody>${Array.from({length:3},(_,i)=>row('stages',i)).join('')}</tbody></table></div>`}
function renderEnterprise(page){const content=document.getElementById('enterpriseContent');if(!content)return;const map={dashboard:()=>dashboard(true),users:()=>tablePage('users',true),checkin:()=>tablePage('checkin',true),learning:()=>tablePage('learning',true),gate:()=>tablePage('gate',true),points:()=>tablePage('points',true),details:()=>tablePage('details',true),promotion:()=>promotion(true)};content.innerHTML=(map[page]||map.dashboard)();document.getElementById('crumb').textContent=labels[page]||labels.dashboard;bindControls()}
function bindControls(){document.querySelectorAll('.side-item').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.side-item').forEach(x=>x.classList.remove('active'));btn.classList.add('active');if(document.getElementById('superContent'))renderSuper(btn.dataset.page);else renderEnterprise(btn.dataset.page)})}
document.addEventListener('DOMContentLoaded',()=>{if(document.getElementById('superContent'))renderSuper('dashboard');if(document.getElementById('enterpriseContent'))renderEnterprise('dashboard')});

/* P0 第二版：赛事创建向导、业务化赛段与精细规则 */
Object.assign(labels,{wizard:'创建竞赛 6 步向导'});
const stageTerms=['报名阶段','初赛阶段','复赛阶段','决赛阶段'];
function competitionWizard(active=1){const steps=['创建赛事','配置赛段','导入参赛单位/用户','配置签到/学习/闯关规则','发布竞赛','查看排行与晋级'];const content=[`<div class="form-row"><label>赛事名称</label><input value="2026 年岗位技能竞赛"/></div><div class="form-row"><label>赛事时间</label><input value="2026-06-01 至 2026-08-31"/></div><div class="form-row"><label>赛事主题</label><input value="以赛促学 · 岗位练兵 · 技能提升"/></div>`,`<div class="wizard-stage-list">${stageTerms.map((x,i)=>`<div><b>${i+1}</b><span>${x}</span><small>${['报名与资格确认','学习、答题与闯关积分累计','专项挑战与晋级筛选','总榜比拼与结果发布'][i]}</small></div>`).join('')}</div>`,`<div class="rule-card"><div class="rule-left"><div class="rule-icon">▦</div><div><b>参赛单位</b><p>已导入 32 家参赛单位</p></div></div>${button('继续导入',false)}</div><div class="rule-card"><div class="rule-left"><div class="rule-icon">♙</div><div><b>参赛用户</b><p>已导入 8,426 名参赛用户</p></div></div>${button('下载模板',false)}</div>`,`<div class="wizard-rule-grid"><div><b>☀ 签到规则</b><small>每日 1 次 · +5 积分 · 连续签到激励</small></div><div><b>▤ 学习规则</b><small>绑定 8 门课程 · 学后答题 · 每日上限</small></div><div><b>⚡ 闯关规则</b><small>5 个分类 · 25 个关卡 · 重复取最高分</small></div></div>`,`<div class="publish-card"><span>✓</span><h2>竞赛配置已就绪</h2><p>完成发布后，参赛用户将看到报名、学习、闯关及积分排行入口。</p>${button('发布竞赛')}</div>`,`<div class="metric-grid"><div class="metric-card"><small>模拟参赛人数</small><b>8,426</b><span>报名完成</span></div><div class="metric-card"><small>晋级候选</small><b>986</b><span>自动计算</span></div><div class="metric-card"><small>排行榜</small><b>TOP 100</b><span>每 5 分钟更新</span></div></div><div class="p1-box">发布后可进入排行榜管理和晋级管理，持续追踪赛事结果。</div>`][active-1];return `<style>.wizard-layout{display:grid;grid-template-columns:235px 1fr;gap:16px}.wizard-nav{padding:9px;background:#fff;border:1px solid var(--line);border-radius:11px}.wizard-step{display:flex;gap:10px;align-items:center;width:100%;padding:12px 10px;text-align:left;background:transparent;border-radius:8px;color:#65738a}.wizard-step b{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;background:#e9eff7;font-size:11px}.wizard-step.active{background:#eef6ff;color:var(--blue);font-weight:700}.wizard-step.active b{color:#fff;background:var(--blue)}.wizard-body{min-height:350px}.wizard-stage-list{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.wizard-stage-list div{padding:15px;border:1px solid #e2eaf5;border-radius:9px}.wizard-stage-list b{display:inline-grid;place-items:center;width:22px;height:22px;border-radius:50%;background:#e8f3ff;color:var(--blue);margin-right:7px}.wizard-stage-list small,.wizard-rule-grid small{display:block;color:#8a97a9;margin:8px 0 0 30px}.wizard-rule-grid{display:grid;gap:10px}.wizard-rule-grid div{padding:15px;border-radius:9px;background:#f8fbff;border:1px solid #e4edf9}.publish-card{text-align:center;padding:46px 20px}.publish-card span{display:inline-grid;place-items:center;width:48px;height:48px;border-radius:50%;background:#e7f8ef;color:var(--green);font-size:24px}.publish-card h2{margin:13px 0 8px}.publish-card p{color:#8390a3;margin-bottom:20px}@media(max-width:850px){.wizard-layout{grid-template-columns:1fr}.wizard-nav{display:flex;overflow:auto}.wizard-step{min-width:165px}.wizard-stage-list{grid-template-columns:1fr}}</style><div class="page-heading"><div><h1>创建竞赛 6 步向导</h1><p>按标准流程完成赛事、赛段、参赛对象、规则与发布配置</p></div><div class="toolbar">${button('保存草稿',false)}${button(active===6?'完成并进入赛事':'下一步',true,active===6?"renderSuper('competitions')":`wizardStep(${active+1})`)}</div></div><div class="wizard-layout"><nav class="wizard-nav">${steps.map((x,i)=>`<button class="wizard-step ${i+1===active?'active':''}" onclick="wizardStep(${i+1})"><b>${i+1}</b><span>${x}</span></button>`).join('')}</nav><section class="form-panel wizard-body"><div class="panel-title"><span>第 ${active} 步 · ${steps[active-1]}</span><a>Mock 数据演示</a></div>${content}</section></div>`}
function wizardStep(step){const target=document.getElementById('superContent');if(!target)return;target.innerHTML=competitionWizard(step);document.getElementById('crumb').textContent=labels.wizard;bindControls()}
function stagesPage(){const stages=[['报名阶段','2026-06-01 至 06-07','已结束','资格确认 8,426 人'],['初赛阶段','2026-06-08 至 06-30','进行中','学习、答题与闯关'],['复赛阶段','2026-07-01 至 07-31','待开始','专项挑战与晋级筛选'],['决赛阶段','2026-08-10 至 08-20','待开始','总榜比拼与结果发布']];const flow=stages.map((x,i)=>`<article class="stage-flow-card ${i===1?'active':''}"><div class="stage-number"><span>赛段 0${i+1}</span><span class="status ${i===1?'green':'gray'}">${x[2]}</span></div><h3>${x[0]}</h3><p>时间：${x[1]}<br/>${x[3]}<br/>支持独立规则与晋级条件</p><div class="stage-foot"><a class="text-link" onclick="showToast('打开赛段配置')">配置规则</a><a class="text-link">查看数据</a></div></article>${i<stages.length-1?'<div class="stage-flow-arrow" aria-label="流程进入下一赛段"><span>➜</span></div>':''}`).join('');return `<div class="page-heading"><div><h1>赛段管理</h1><p>以可扩展的赛事流程编排赛段，支持根据不同赛事按需新增、调整或串联赛段</p></div><div class="toolbar">${button('新建赛段',true,"showToast('已打开新增赛段配置（原型演示）')")}</div></div><section class="panel"><div class="panel-title"><span>2026 年岗位技能竞赛 · 赛事流程</span><a onclick="showToast('可拖拽调整赛段顺序（P1）')">调整流程顺序</a></div><div class="stage-flow">${flow}<button class="stage-add" onclick="showToast('可在此插入新的赛事赛段')"><b>+</b><strong>新增赛段</strong><small>可插入任意流程节点</small></button></div></section><div class="p1-box">赛事流程模板、赛段拖拽排序和分支赛道配置（P1） · 当前原型展示为可连续扩展的线性赛程</div><div class="data-table-wrap" style="margin-top:14px"><table class="data-table"><thead><tr><th>赛段名称</th><th>起止时间</th><th>积分池</th><th>晋级条件</th><th>状态</th><th>操作</th></tr></thead><tbody>${stages.map((x,i)=>`<tr><td>${x[0]}</td><td>${x[1]}</td><td>${['0','2,000 分','3,000 分','5,000 分'][i]}</td><td>${i===0?'完成资格确认':i===1?'累计积分 ≥ 1,500':i===2?'积分排名前 300':'总榜前 50'}</td><td><span class="status ${i===1?'green':'gray'}">${x[2]}</span></td><td><a class="text-link">编辑</a><a class="text-link">查看数据</a></td></tr>`).join('')}</tbody></table></div>`}
function configPage(type,title,desc){const fields={checkin:[['每日次数','1 次'],['签到积分','5 积分'],['连续签到','连续 7 天额外奖励 20 积分'],['断签规则','断签后连续天数重新计算'],['积分上限','每赛段最多 200 积分']],learning:[['绑定课程','初赛必修课程包（8 门）'],['有效学习比例','视频/图文完成比例 ≥ 80%'],['学后答题','开启，完成学习后自动触发'],['通过分数','≥ 80 分'],['每日上限','每日最多获得 60 学习积分']],gate:[['关卡数量','5 个分类，共 25 关'],['题目数量','每关 3 题'],['题目来源','竞赛题库 · 安全生产专题'],['通关正确率','≥ 80%'],['挑战次数','每关每日 3 次'],['重复挑战规则','保留最高得分，仅首次通关发放基础积分']]}[type];return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="toolbar">${button('保存配置')}</div></div><div class="config-grid"><section class="form-panel"><h3 style="margin-top:0">${type==='checkin'?'签到':type==='learning'?'学习':'闯关'}规则字段</h3><div class="form-row"><label>适用赛事</label><select><option>2026 年岗位技能竞赛</option></select></div><div class="form-row"><label>适用赛段</label><select><option>初赛阶段</option></select></div>${fields.map(([label,value])=>`<div class="form-row"><label>${label}</label><input value="${value}"/></div>`).join('')}<div style="text-align:right;margin-top:30px">${button('预览用户端',false,"showToast('已打开用户端规则预览')")} ${button('保存并发布')}</div></section><section class="form-panel"><div class="panel-title"><span>配置说明</span><a>规则示例</a></div>${fields.map((r,i)=>`<div class="rule-card"><div class="rule-left"><div class="rule-icon">${['✓','✦','●','☀','↗','◇'][i]}</div><div><b>${r[0]}</b><p>${r[1]}</p></div></div><div class="toggle"></div></div>`).join('')}<div class="p1-box">复杂积分公式与规则版本回溯（P1）</div></section></div>`}
function promotion(enterprise=false){const verb=enterprise?'提交晋级推荐':'确认晋级';return `<div class="page-heading"><div><h1>${enterprise?'条件晋级':'晋级管理'}</h1><p>${enterprise?'识别本单位满足条件的用户，提交晋级推荐；最终晋级名单由超级管理员统一发布':'按赛段规则自动计算候选名单，复核后发布正式晋级名单'}</p></div><div class="toolbar">${button('导出候选名单',false,"showToast('候选名单已导出')")}${enterprise?button('提交晋级推荐'):button('发布晋级名单',true,"showToast('晋级名单已发布，参赛用户可查看结果')")}</div></div><div class="promotion-board"><section class="promotion-card"><span class="status blue">当前赛段 · 初赛阶段</span><h3 style="margin-top:13px">晋级条件</h3><div class="promotion-score">≥ 1,500</div><p style="color:#8290a5">累计积分达到门槛，且完成 2 门必修课程、3 个闯关分类</p><div class="p1-box">自动补位、同分排序及申诉流程（P1）</div></section><section class="promotion-card"><span class="status green">自动计算结果</span><h3 style="margin-top:13px">本轮候选</h3><div class="promotion-score">${enterprise?'158':'986'} 人</div><p style="color:#8290a5">${enterprise?'已满足条件 · 待提交超级管理员审核':'已满足赛事规则 · 待发布正式晋级名单'}</p><button class="btn-primary" style="margin-top:16px" onclick="showToast('已完成候选条件复核')">重新计算候选</button></section></div><div class="data-table-wrap" style="margin-top:14px"><div class="table-filter"><input placeholder="搜索姓名、工号"/><select><option>全部结果</option><option>符合条件</option><option>待补齐任务</option></select>${button('筛选')}</div><table class="data-table"><thead><tr><th>用户</th><th>所属单位</th><th>当前积分</th><th>必修课</th><th>闯关分类</th><th>条件判定</th><th>${enterprise?'推荐状态':'晋级状态'}</th><th>操作</th></tr></thead><tbody>${names.slice(0,6).map((n,i)=>`<tr><td>${n}</td><td>千铝工投</td><td>${1830-i*55}</td><td>2 / 2</td><td>${3+i%2} / 3</td><td><span class="status green">符合条件</span></td><td>${i===0?'<span class="status blue">已提交</span>':enterprise?'<span class="status orange">待推荐</span>':'<span class="status orange">待发布</span>'}</td><td><a class="text-link" onclick="showToast('已更新${verb}状态')">${verb}</a></td></tr>`).join('')}</tbody></table></div>`}
function renderSuper(page){const content=document.getElementById('superContent');if(!content)return;const map={dashboard:()=>dashboard(),wizard:()=>competitionWizard(),competitions:()=>tablePage('competitions'),stages:()=>stagesPage(),units:()=>tablePage('units'),users:()=>tablePage('users'),checkin:()=>tablePage('checkin'),learning:()=>tablePage('learning'),gate:()=>tablePage('gate'),points:()=>tablePage('points'),ranking,promotion:()=>promotion(false)};content.innerHTML=(map[page]||map.dashboard)();document.getElementById('crumb').textContent=labels[page]||labels.dashboard;bindControls()}
document.addEventListener('DOMContentLoaded',()=>{if(document.querySelector('.h5-page')){h5Go('login');document.querySelectorAll('#points .point-record').forEach(x=>{if(x.textContent.includes('积分兑换'))x.remove()});document.querySelectorAll('#points .empty-p1').forEach(x=>x.remove());const replacements=[['基础能力提升赛','初赛阶段'],['基础赛段','初赛阶段'],['基础赛','初赛阶段'],['专项技能挑战赛','复赛阶段'],['专项赛','复赛阶段']];const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{replacements.forEach(([from,to])=>{node.nodeValue=node.nodeValue.replaceAll(from,to)})})}});
